 // 逗号分隔\n  alert_threshold    Int       @default(3) @db.SmallInt // 连续失败 N 次告警\n  fail_count         Int       @default(0) @db.SmallInt // 连续失败计数\n  dependency_job_ids Json?     @map(\"dependency_job_ids\") // 依赖的前置任务 ID 数组\n  dependency_mode    String?   @default(\"all\") @db.VarChar(8) // all / any\n  on_dependency_fail String?   @default(\"skip\") @db.VarChar(16) // skip / abort\n  run_after_success  Boolean   @default(true) @map(\"run_after_success\")\n\n  @@index([tenant_id])\n  @@map(\"sys_job\")\n}\n\nmodel sys_job_log {\n  log_id         String   @id @default(uuid()) @db.Uuid\n  job_id         String   @db.Uuid\n  job_name       String   @db.VarChar(128)\n  invoke_target  String   @db.VarChar(256)\n  job_message    String?  @db.VarChar(512)\n  status         String   @default(\"1\") @db.VarChar(10)\n  exception_info String?  @db.Text\n  created_at     DateTime @default(now()) @db.Timestamptz(6)\n  retry_attempt  Int      @default(0) @db.SmallInt\n  duration_ms    Int      @default(0) @db.Integer /// 执行时长（毫秒）\n  created_by     String?  @db.Uuid /// 创建人ID\n\n  @@index([job_id])\n  @@index([created_at])\n  @@map(\"sys_job_log\")\n}\n\nmodel sys_job_run {\n  run_id         String    @id @default(uuid()) @db.Uuid\n  tenant_id      String    @db.Uuid\n  job_id         String    @db.Uuid\n  triggered_by   String    @db.VarChar(32) // cron / manual / dependency / retry\n  trigger_parent String?   @db.Uuid // 上游 run_id\n  status         String    @db.VarChar(16) // running / success / failed / skipped\n  started_at     DateTime  @default(now()) @db.Timestamptz()\n  finished_at    DateTime? @db.Timestamptz()\n  duration_ms    Int?\n  error_msg      String?\n\n  @@index([job_id, started_at(sort: Desc)])\n  @@index([status])\n  @@map(\"sys_job_run\")\n}\n\nmodel sys_todo {\n  todo_id    String    @id @default(uuid()) @db.Uuid\n  tenant_id  String    @db.Uuid\n  user_id    String    @db.Uuid\n  title      String    @db.VarChar(256)\n  content    String?   @db.Text\n  priority   Int       @default(0) @db.SmallInt\n  due_time   DateTime? @db.Timestamptz(6)\n  created_by String?   @db.Uuid\n  updated_by String?   @db.Uuid\n  status     String    @default(\"0\") @db.VarChar(10)\n  created_at DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at DateTime  @updatedAt @db.Timestamptz(6)\n  is_deleted Int       @default(0) @db.SmallInt\n  group_id   String?   @db.Uuid\n  remind_at  DateTime? @db.Timestamptz(6)\n  reminded   Int       @default(0) @db.SmallInt // 是否已提醒\n  tags       String?   @db.VarChar(256) // 逗号分隔\n\n  @@index([tenant_id, user_id])\n  @@index([status])\n  @@map(\"sys_todo\")\n}\n\nmodel sys_ip_rule {\n  rule_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  rule_type  String   @db.VarChar(10)\n  ip_pattern String   @db.VarChar(64)\n  remark     String?  @db.VarChar(256)\n  status     String   @default(\"1\") @db.VarChar(10)\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @updatedAt @db.Timestamptz(6)\n  created_by String?  @db.Uuid\n  updated_by String?  @db.Uuid\n  is_deleted Int      @default(0) @db.SmallInt\n\n  @@index([tenant_id, rule_type])\n  @@map(\"sys_ip_rule\")\n}\n\n/// 通知渠道配置（每租户一份）\nmodel sys_notice_channel {\n  channel_id   String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  channel_type String   @db.VarChar(32) /// email | sms | webhook | wechat_work | dingtalk\n  enabled      Int      @default(0) @db.SmallInt\n  config       String?  @db.Text /// JSON 配置（SMTP/SMS 签名/Webhook URL 等）\n  remark       String?  @db.VarChar(256)\n  created_at   DateTime @default(now()) @db.Timestamptz(6)\n  updated_at   DateTime @updatedAt @db.Timestamptz(6)\n  created_by   String?  @db.Uuid\n  updated_by   String?  @db.Uuid\n  is_deleted   Int      @default(0) @db.SmallInt\n\n  @@unique([tenant_id, channel_type])\n  @@index([tenant_id])\n  @@map(\"sys_notice_channel\")\n}\n\n/// 通知发送日志\nmodel sys_notice_send_log {\n  log_id       String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  notice_id    String?  @db.Uuid\n  channel_type String   @db.VarChar(32)\n  receiver     String   @db.VarChar(256) /// 邮箱/手机号/URL\n  status       String   @default(\"1\") @db.VarChar(10)\n  error_msg    String?  @db.Text\n  created_at   DateTime @default(now()) @db.Timestamptz(6) /// 创建时间\n  created_by   String?  @db.Uuid /// 创建人ID\n\n  @@index([tenant_id, channel_type])\n  @@index([notice_id])\n  @@index([created_at])\n  @@map(\"sys_notice_send_log\")\n}\n\nmodel sys_password_history {\n  id         String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  user_id    String   @db.Uuid\n  password   String   @db.VarChar(256)\n  created_at DateTime @default(now()) @db.Timestamptz(6) /// 创建时间\n  created_by String?  @db.Uuid /// 创建人ID\n\n  @@index([tenant_id, user_id, created_at])\n  @@map(\"sys_password_history\")\n}\n\nmodel sys_todo_group {\n  group_id   String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  user_id    String   @db.Uuid\n  name       String   @db.VarChar(64)\n  color      String?  @db.VarChar(16)\n  sort_order Int      @default(0)\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @updatedAt @db.Timestamptz(6)\n  is_deleted Int      @default(0) @db.SmallInt\n  created_by String?  @db.Uuid\n  updated_by String?  @db.Uuid\n\n  @@index([tenant_id, user_id])\n  @@map(\"sys_todo_group\")\n}\n\nmodel sys_user_tenant {\n  id         String   @id @default(uuid()) @db.Uuid\n  user_id    String   @db.Uuid\n  tenant_id  String   @db.Uuid\n  is_default Int      @default(0) @db.SmallInt\n  joined_at  DateTime @default(now()) @db.Timestamptz(6) /// 加入时间\n  created_by String?  @db.Uuid /// 创建人ID\n\n  @@unique([user_id, tenant_id])\n  @@index([user_id])\n  @@index([tenant_id])\n  @@map(\"sys_user_tenant\")\n}\n\nmodel gen_table {\n  table_id        String   @id @default(uuid()) @db.Uuid\n  table_name      String   @unique @db.VarChar(200)\n  table_comment   String?  @db.VarChar(500)\n  class_name      String   @db.VarChar(100)\n  tpl_category    String   @default(\"crud\") @db.VarChar(20)\n  package_name    String?  @db.VarChar(100)\n  module_name     String?  @db.VarChar(30)\n  business_name   String?  @db.VarChar(30)\n  function_name   String?  @db.VarChar(50)\n  function_author String?  @db.VarChar(50)\n  table_status    String   @default(\"pending\") @db.VarChar(20) // pending / created / altered\n  // 规范字段\n  tenant_id       String   @db.Uuid\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n  created_by      String?  @db.Uuid\n  updated_by      String?  @db.Uuid\n  is_deleted      Int      @default(0) @db.SmallInt\n\n  // 无数据库外键，应用层维护\n  columns gen_table_column[]\n\n  @@index([tenant_id])\n  @@index([is_deleted])\n  @@map(\"gen_table\")\n}\n\nmodel gen_table_column {\n  column_id         String     @id @default(uuid()) @db.Uuid\n  table_id          String     @db.Uuid\n  column_name       String     @db.VarChar(200)\n  column_comment    String?    @db.VarChar(500)\n  column_type       String     @db.VarChar(100) // varchar(64) / int4 / uuid ...\n  ts_type           String?    @db.VarChar(50) // string / number / Date ...\n  field_name        String?    @db.VarChar(200) // camelCase\n  is_pk             String     @default(\"0\") @db.Char(1)\n  is_increment      String     @default(\"0\") @db.Char(1)\n  is_required       String     @default(\"0\") @db.Char(1)\n  is_insert         String     @default(\"1\") @db.Char(1)\n  is_edit           String     @default(\"1\") @db.Char(1)\n  is_list           String     @default(\"1\") @db.Char(1)\n  is_query          String     @default(\"0\") @db.Char(1)\n  is_sort           String     @default(\"0\") @db.Char(1) // 是否参与排序\n  query_type        String     @default(\"EQ\") @db.VarChar(20)\n  html_type         String     @default(\"input\") @db.VarChar(20)\n  dict_type         String?    @db.VarChar(200)\n  default_value     String?    @db.VarChar(200)\n  sort              Int?\n  is_deleted        Int        @default(0) @db.SmallInt\n  genTable          gen_table? @relation(fields: [gen_tableTable_id], references: [table_id])\n  gen_tableTable_id String?    @db.Uuid\n\n  @@index([table_id])\n  @@index([table_id, is_deleted])\n  @@map(\"gen_table_column\")\n}\n\nmodel sys_upload_task {\n  task_id      String   @id @default(uuid())\n  upload_id    String\n  file_name    String\n  total_chunks Int\n  status       String // pending | merging | uploading | completed | failed\n  progress     Int      @default(0) // 0 ~ 100\n  error_msg    String?\n  file_id      String?\n  url          String?\n  size         BigInt?\n  tenant_id    String?\n  user_id      String?\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  @@index([upload_id])\n  @@index([status])\n  @@map(\"sys_upload_task\")\n}\n\n/// 每日审计聚合（保留 2 年）\nmodel sys_audit_daily {\n  id          String   @id @default(uuid()) @db.Uuid\n  tenant_id   String   @db.Uuid\n  stat_date   DateTime @db.Date\n  operation   String   @db.VarChar(128)\n  total_count Int      @default(0)\n  fail_count  Int      @default(0)\n  avg_time_ms Int      @default(0)\n  p95_time_ms Int      @default(0)\n\n  @@unique([tenant_id, stat_date, operation])\n  @@index([tenant_id, stat_date])\n  @@map(\"sys_audit_daily\")\n}\n\n/// 每日登录聚合\nmodel sys_login_daily {\n  id           String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  stat_date    DateTime @db.Date\n  total_count  Int      @default(0)\n  fail_count   Int      @default(0)\n  unique_users Int      @default(0)\n\n  @@unique([tenant_id, stat_date])\n  @@map(\"sys_login_daily\")\n}\n\n// ==================== 审批申请主表 ====================\nmodel sys_approval_request {\n  request_id      String   @id @default(uuid()) @db.Uuid\n  tenant_id       String   @db.Uuid\n  title           String   @db.VarChar(256)\n  content         String?  @db.Text\n  form_data       Json?\n  applicant_id    String   @db.Uuid\n  current_dept_id String   @db.Uuid\n  status          String   @default(\"0\") @db.VarChar(20)\n  is_deleted      Int      @default(0) @db.SmallInt\n  created_at      DateTime @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime @updatedAt @db.Timestamptz(6)\n  created_by      String?  @db.Uuid\n  updated_by      String?  @db.Uuid\n\n  // ===== 反向关系字段 =====\n  nodes sys_approval_node[]\n  logs  sys_approval_log[]\n\n  @@index([tenant_id, status])\n  @@index([tenant_id, applicant_id])\n  @@index([is_deleted])\n  @@map(\"sys_approval_request\")\n}\n\n// ==================== 审批节点表 ====================\nmodel sys_approval_node {\n  node_id            String    @id @default(uuid()) @db.Uuid\n  tenant_id          String    @db.Uuid\n  request_id         String    @db.Uuid\n  dept_id            String    @db.Uuid\n  approver_id        String?   @db.Uuid\n  sequence           Int\n  status             String    @default(\"0\") @db.VarChar(20)\n  is_current         Int       @default(0) @db.SmallInt\n  round              Int       @default(1)\n  reject_reason_type String?   @db.VarChar(64)\n  reject_reason      String?   @db.VarChar(512)\n  approved_at        DateTime? @db.Timestamptz(6)\n  is_deleted         Int       @default(0) @db.SmallInt\n  created_at         DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at         DateTime  @updatedAt @db.Timestamptz(6)\n  created_by         String?   @db.Uuid\n  updated_by         String?   @db.Uuid\n\n  // ===== 关系字段 =====\n  request sys_approval_request @relation(fields: [request_id], references: [request_id], onDelete: Cascade)\n\n  @@index([tenant_id, request_id])\n  @@index([tenant_id, dept_id, status])\n  @@map(\"sys_approval_node\")\n}\n\n// ==================== 审批操作日志表 ====================\nmodel sys_approval_log {\n  log_id        String   @id @default(uuid()) @db.Uuid\n  tenant_id     String   @db.Uuid\n  request_id    String   @db.Uuid\n  operator_id   String   @db.Uuid\n  operator_name String   @db.VarChar(64)\n  action        String   @db.VarChar(32)\n  from_status   String?  @db.VarChar(20)\n  to_status     String?  @db.VarChar(20)\n  remark        String?  @db.Text\n  reason_type   String?  @db.VarChar(64)\n  metadata      Json?\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n  created_by    String?  @db.Uuid\n\n  // ===== 关系字段 =====\n  request sys_approval_request @relation(fields: [request_id], references: [request_id], onDelete: Cascade)\n\n  @@index([tenant_id, request_id])\n  @@index([created_at])\n  @@map(\"sys_approval_log\")\n}\n\nmodel sys_notice_template {\n  template_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id      String   @db.Uuid\n  template_code  String   @db.VarChar(64)\n  template_name  String   @db.VarChar(128)\n  channel_type   String   @db.VarChar(32)\n  title          String?  @db.VarChar(256)\n  content        String   @db.Text\n  content_format String   @default(\"markdown\") @db.VarChar(16)\n  remark         String?  @db.VarChar(512)\n  params         Json?\n  status         String   @default(\"1\")\n  created_at     DateTime @default(now())\n  updated_at     DateTime @updatedAt\n  created_by     String?  @db.Uuid\n  updated_by     String?  @db.Uuid\n  is_deleted     Int      @default(0) @db.SmallInt\n\n  @@unique([tenant_id, template_code])\n  @@map(\"sys_notice_template\")\n}\n\nmodel sys_file_pending_delete {\n  id          String   @id @default(uuid()) @db.Uuid\n  tenant_id   String   @db.Uuid\n  url         String\n  retry_count Int      @default(0)\n  next_retry  DateTime @default(now())\n  last_error  String?\n  created_at  DateTime @default(now())\n\n  @@index([next_retry])\n}\n",
